function buildReportV3(document,jsonPayload){const base=buildReport(document,jsonPayload).toString().trimEnd();const audit=task34AuditRows();const rows=audit.map(row=>`| ${row.relative_path} | ${row.baseline_sha256} | ${row.current_sha256} | ${row.status} |`);const red=baselineRedEvidence;return Buffer.from([base,'','## Fix3 complete Task34 changed-file audit','',`This table supersedes the earlier abbreviated audit. It is the complete Task34-owned delta against frozen baseline ${red.baseline_snapshot}. Separate Task35/39 frontend/profile files are intentionally excluded.` ,'', '| Task34-owned relative path | Frozen baseline SHA-256 | Current SHA-256 or generation marker | Disposition |','| --- | --- | --- | --- |',...rows,'','## Fix3 observed seven-test RED reconstruction','', 'This is a current reproducible reconstruction, not a historical transcript copied from an intermediate checkout. The frozen baseline package contains exactly 8 render cases, 23 mutation rows, and no diagnostic witness. The current converted seven-test unittest module was retained unchanged in the scratch overlay.','',`Reconstruction: ${red.reconstruction}.`,'', 'Exact command:', '```sh', red.command, '```','', 'Observed status lines (all seven discovered tests):','```text',...red.statuses,'```','',`Observed summary: ${red.failure_count} failures, ${red.error_count} errors, ${red.pass_count} passes; ${red.summary}.`,'', 'Load-bearing observed failure output:', '```text',...red.observations,'```','',`Captured streams: stdout ${red.stdout_bytes} bytes (SHA-256 ${red.stdout_sha256}); stderr ${red.stderr_bytes} bytes (SHA-256 ${red.stderr_sha256}).`,'',`Disk hygiene: ${red.cleanup}`,'','## Fix3 evidence boundary','', 'The RED reconstruction is evidence that the current seven-test module rejects the frozen package for the recorded reasons. It is not a claim that the old pytest module itself was a seven-test unittest run. The live package remains the 18/25/1 package and its live seven-test gate is green.',''].join('\n')+'\n')}
